1	import { test } from "node:test";
2	import assert from "node:assert/strict";
3	import { readFileSync } from "node:fs";
4	import { renewalQuote } from "../lib/renewal-quote.ts";
5	import { vpsTermPriceCents } from "../lib/billing-terms.ts";
6	
7	/**
8	 * The three launch blockers found by the 2026-07-26 customer-journey rehearsal.
9	 * All three were OBSERVED in a browser, not inferred, and all three were live in
10	 * production when they were found.
11	 *
12	 * They share one shape: a number or an action the customer sees is not the number
13	 * or the action the system performs. That is the same defect class the migration
14	 * engine spent this whole session removing, arriving on the purchase path — where
15	 * it takes money instead of misreporting a server.
16	 *
17	 * The source tripwires below are deliberately structural rather than behavioural.
18	 * Two of these bugs live in React rendering, which cannot be exercised without a
19	 * DOM; asserting on the source is weaker than a real interaction test but it is
20	 * infinitely stronger than nothing, and it fails loudly the moment the shape that
21	 * caused the incident reappears.
22	 */
23	
24	/* ------------------------------------------------------------------ *
25	 * 1. The wizard charged four steps before the Review screen
26	 *    Reproduced 5×: 5 servers created, 5 wallet debits, no total ever shown.
27	 *    Continue and Deploy were two branches of an UNKEYED ternary at the same
28	 *    position in the tree, so React reused one DOM node for both — advancing the
29	 *    step mutated the live Continue button into a submit control mid-click.
30	 * ------------------------------------------------------------------ */
31	
32	/**
33	 * Source with comments removed.
34	 *
35	 * Every fix here carries a comment quoting the bug it fixed — "the label read
36	 * `Renew now (+30 days, $8.99)`", "this hardcoded `exampleRegular = 500`". A
37	 * tripwire that greps raw source therefore matches its own incident note and
38	 * fails on correct code, which is how a guard trains people to ignore it. These
39	 * assertions look at what the file DOES, not at what it says about its past.
40	 */
41	function code(relative: string): string {
42	  return readFileSync(new URL(relative, import.meta.url), "utf8")
43	    .replace(/\/\*[\s\S]*?\*\//g, "")
44	    .replace(/^\s*\/\/.*$/gm, "");
45	}
46	
47	const WIZARD = code("../components/customer/DeployWizard.tsx");
48	
49	test("the wizard's Continue and Deploy buttons can never be reconciled as one node", () => {
50	  assert.match(WIZARD, /key="wizard-continue"/, "the Continue branch is keyed");
51	  assert.match(WIZARD, /key="wizard-deploy"/, "the Deploy branch is keyed");
52	  // Both must state their type. The incident happened because one branch relied
53	  // on the HTML default (`submit` inside a form) while the other set it.
54	  assert.match(WIZARD, /key="wizard-continue"\s+type="button"/, "Continue is explicitly type=button");
55	  assert.match(WIZARD, /key="wizard-deploy"\s+type="submit"/, "Deploy is explicitly type=submit");
56	});
57	
58	test("the wizard form refuses to submit anywhere but the final step", () => {
59	  // The safety net that does not depend on getting JSX reconciliation right.
60	  // Before this, the only guard was an onKeyDown that covered the Enter key —
61	  // and the incident was driven by a CLICK.
62	  assert.match(WIZARD, /onSubmit=\{\(e\) => \{\s*if \(!isLast\) \{\s*e\.preventDefault\(\)/,
63	    "a non-final submit is cancelled outright");
64	});
65	
66	/* ------------------------------------------------------------------ *
67	 * 2. "Renew now (+30 days, $8.99)" charged $97.09 and added 12 months
68	 * ------------------------------------------------------------------ */
69	
70	test("the renewal quote charges the term it advertises, not a month", () => {
71	  // Starter at $8.99 on a 12-month term — the exact server from the incident.
72	  const q = renewalQuote({
73	    planPriceCents: 899,
74	    termMonths: 12,
75	    hasDedicatedIp: false,
76	    dedicatedIpMonthlyCents: 0,
77	    extraDiskMonthlyCents: 0,
78	  });
79	  assert.equal(q.months, 12, "a 12-month term renews by 12 months, not 30 days");
80	  assert.equal(q.durationLabel, "12 months");
81	  assert.equal(q.totalCents, vpsTermPriceCents(899, 12), "the quote IS the term price");
82	  // The incident: the button rendered the monthly figure for a term charge.
83	  assert.notEqual(q.totalCents, 899, "quoting the monthly price for a term charge was a 10.8x understatement");
84	  assert.ok(q.totalCents > 899 * 10, `expected an order-of-magnitude gap, got ${q.totalCents}`);
85	});
86	
87	test("a monthly server still renews by exactly one month, labelled singular", () => {
88	  const q = renewalQuote({
89	    planPriceCents: 899,
90	    termMonths: 1,
91	    hasDedicatedIp: false,
92	    dedicatedIpMonthlyCents: 0,
93	    extraDiskMonthlyCents: 0,
94	  });
95	  assert.equal(q.months, 1);
96	  assert.equal(q.durationLabel, "1 month", "not '1 months'");
97	  assert.equal(q.totalCents, 899);
98	});
99	
100	test("surcharges are billed for the whole term, exactly as the action charges them", () => {
101	  const q = renewalQuote({
102	    planPriceCents: 899,
103	    termMonths: 12,
104	    hasDedicatedIp: true,
105	    dedicatedIpMonthlyCents: 300,
106	    extraDiskMonthlyCents: 500,
107	  });
108	  assert.equal(q.totalCents, vpsTermPriceCents(899, 12) + 300 * 12 + 500 * 12);
109	  // A dedicated IP that is not allocated is never charged, however it was flagged.
110	  const noIp = renewalQuote({
111	    planPriceCents: 899,
112	    termMonths: 12,
113	    hasDedicatedIp: false,
114	    dedicatedIpMonthlyCents: 300,
115	    extraDiskMonthlyCents: 0,
116	  });
117	  assert.equal(noIp.totalCents, vpsTermPriceCents(899, 12));
118	});
119	
120	test("the renew button and the renew action price through the SAME function", () => {
121	  const actions = code("../lib/actions.ts");
122	  const page = code("../app/dashboard/servers/[id]/page.tsx");
123	  const card = code("../components/SubscriptionControls.tsx");
124	  assert.match(actions, /renewalQuote\(\{/, "renewNow charges through the shared quote");
125	  assert.match(page, /renewalQuote\(\{/, "the page quotes through the shared quote");
126	  assert.match(page, /renewTotalCents=\{renewQuote\.totalCents\}/, "the real total is passed to the card");
127	  assert.match(page, /renewDurationLabel=\{renewQuote\.durationLabel\}/, "the real duration is passed too");
128	  // The card must not re-derive a price. `totalMonthlyCents` is a MONTHLY figure
129	  // and rendering it as the renewal charge is precisely what went wrong.
130	  assert.ok(
131	    !/Renew now \(\+30 days/.test(card),
132	    "the hardcoded '+30 days' label is gone"
133	  );
134	  // `totalMonthlyCents` may still exist — it renders the honest "$X/mo" rate row.
135	  // What must never happen again is that MONTHLY figure being used as the
136	  // renewal charge, which is the substitution that turned $8.99 into $97.09.
137	  const renewButton = /className="btn-primary mt-4 w-full"[\s\S]*?<\/button>/.exec(card)?.[0] ?? "";
138	  assert.ok(renewButton, "found the renew button");
139	  assert.ok(
140	    !renewButton.includes("totalMonthlyCents"),
141	    "the renew button never prices itself from the monthly rate"
142	  );
143	  assert.ok(
144	    renewButton.includes("renewTotalCents") && renewButton.includes("renewDurationLabel"),
145	    "it renders only the server-computed quote"
146	  );
147	});
148	
149	test("renewing takes one confirmation naming the real amount and duration", () => {
150	  const card = code("../components/SubscriptionControls.tsx");
151	  assert.match(card, /window\.confirm\(/, "an irreversible wallet debit is confirmed");
152	  assert.match(card, /renewDurationLabel/, "the confirmation states the real duration");
153	  assert.match(card, /renewTotalCents \/ 100/, "the confirmation states the real amount");
154	});
155	
156	/* ------------------------------------------------------------------ *
157	 * 3. The promo bar advertised "VPS from $5 → $3.50/mo" — a price nobody
158	 *    could buy, on every marketing page, while the same page rendered $8.99.
159	 * ------------------------------------------------------------------ */
160	
161	test("the promo bar reads its headline price from the catalogue, never a literal", () => {
162	  const bar = code("../components/marketing/PromoBar.tsx");
163	  assert.ok(!/exampleRegular = \d+/.test(bar), "no hardcoded price survives in the promo bar");
164	  assert.match(bar, /db\.plan\.findFirst/, "the price comes from the plan catalogue");
165	  assert.match(bar, /orderBy: \{ priceCents: "asc" \}/, "and it is genuinely the cheapest plan");
166	  assert.match(bar, /where: \{ active: true \}/, "an inactive plan is not purchasable and must not be advertised");
167	  // A price with cents must render its cents: $8.99 shown as "$9" is still a
168	  // false claim, just a smaller one.
169	  assert.ok(!/exampleRegular \/ 100\)\.toFixed\(0\)/.test(bar), "prices render to 2dp");
170	  // No sellable plan means no honest claim is available, so none is made.
171	  assert.match(bar, /return null/, "the bar renders nothing rather than inventing a price");
172	});
