42	/** Cookie the register page sets when a visitor arrives via a referral link. */
43	const REF_COOKIE = "nxeon_ref";
44	/** Cookie the billing CouponField sets when a promo code is applied. */
45	const COUPON_COOKIE = "nxeon_coupon";
