47	/** Allocate a referral code that is unique in the DB (retry on the rare clash). */
48	async function uniqueReferralCode(): Promise<string> {
49	  for (let i = 0; i < 6; i++) {
50	    const code = generateReferralCode();
51	    const clash = await db.user.findUnique({ where: { referralCode: code } });
52	    if (!clash) return code;
53	  }
54	  // Extremely unlikely; fall back to a longer code.
55	  return generateReferralCode(12);
56	}
