58	async function audit(userId: string | null, action: string, detail?: string) {
59	  // Attribute to the real admin when an admin is impersonating, so customer-scoped
60	  // actions taken during impersonation aren't logged as if the customer did them.
61	  const imp = await impersonating();
62	  const actor = imp ? `actingAdmin=${imp.admin.id}` : "";
63	  const fullDetail = detail && actor ? `${detail} ${actor}` : detail || actor || undefined;
64	  await db.auditLog.create({ data: { userId, action, detail: fullDetail } });
65	}
