67	/** Local sentinel: renewNow's compare-and-swap lost the race (already renewed). */
68	class AlreadyRenewedError extends Error {
69	  constructor() {
70	    super("ALREADY_RENEWED");
71	    this.name = "AlreadyRenewedError";
72	  }
73	}
