148	export async function login(
149	  prev: any,
150	  formData: FormData,
151	): Promise<{ error?: string; needs2fa?: boolean }> {
152	  const parsed = credsSchema.safeParse({
153	    email: formData.get("email"),
154	    password: formData.get("password"),
155	  });
156	  if (!parsed.success) return { error: "Invalid email or password." };
157	
158	  // App-level throttle per email+IP over a 15 min window. The max-attempts cap is
159	  // admin-configurable (`login_ratelimit_max`, default 10) rather than hardcoded.
160	  const hdrs = await headers();
161	  const ip = (hdrs.get("x-forwarded-for") ?? "").split(",")[0]?.trim() || "unknown";
162	  const rlId = `${parsed.data.email}:${ip}`;
163	  const maxAttempts = Math.max(1, await getSettingInt("login_ratelimit_max", 10));
164	  const rl = checkRateLimit(`login:${rlId}`, { max: maxAttempts, windowMs: 15 * 60 * 1000 });
165	  if (!rl.ok) return { error: `Too many attempts. Try again in ${rl.retryAfterSec}s.` };
166	
167	  const user = await db.user.findUnique({ where: { email: parsed.data.email } });
168	  if (!user || !(await bcrypt.compare(parsed.data.password, user.passwordHash))) {
169	    return { error: "Invalid email or password." };
170	  }
171	  if (user.suspended) return { error: "This account is suspended." };
172	
173	  // Two-factor challenge, if enabled on the account.
174	  if (user.totpEnabled) {
175	    const code = String(formData.get("code") ?? "").trim();
176	    if (!code) return { error: "Enter your 2FA code to continue.", needs2fa: true };
177	    if (!(await verifyTotpForUser(user.id, code))) {
178	      return { error: "Invalid 2FA code.", needs2fa: true };
179	    }
180	  }
181	
182	  resetRateLimit(`login:${rlId}`);
183	  await audit(user.id, "user.login");
184	  await createSession(user.id);
185	  redirect(user.role === "ADMIN" ? "/admin" : "/dashboard");
186	}
