205	/** Pick the least-committed enabled node (RAM headroom). Falls back to primary. */
206	async function scheduleNode(planRamMB: number) {
207	  const nodes = await db.node.findMany({ where: { enabled: true, status: "ONLINE" } });
208	  if (nodes.length === 0) return null;
209	  const loads = await Promise.all(
210	    nodes.map(async (n) => {
211	      const agg = await db.server.findMany({
212	        where: { nodeId: n.id, status: { notIn: ["DELETING"] } },
213	        select: { plan: { select: { ramMB: true } } },
214	      });
215	      const used = agg.reduce((s, r) => s + r.plan.ramMB, 0);
216	      return { node: n, free: n.capacityRamMB - used };
217	    })
218	  );
219	  loads.sort((a, b) => b.free - a.free);
220	  const best = loads[0];
221	  if (best.free < planRamMB) return best.node; // oversell guard handled by capacityCheck; still return best
222	  return best.node;
223	}
