225	/**
226	 * Enforce the admin-configured per-user server cap (`max_servers_per_user`,
227	 * default 10; 0 = unlimited). Counts every server the user owns that isn't being
228	 * torn down (DELETING). Returns an error message when the cap is reached, else null.
229	 */
230	async function serverLimitError(userId: string): Promise<string | null> {
231	  const cap = await getSettingInt("max_servers_per_user", 10);
232	  if (cap <= 0) return null; // 0 (or negative) = unlimited
233	  const owned = await db.server.count({ where: { userId, status: { notIn: ["DELETING"] } } });
234	  if (owned >= cap) {
235	    return `You've reached your limit of ${cap} server${cap === 1 ? "" : "s"}. Delete one or contact support to raise the cap.`;
236	  }
237	  return null;
238	}
