21	export async function updateProfile(prev: any, formData: FormData): Promise<{ error?: string; ok?: boolean }> {
22	  const user = await requireUser();
23	  const name = String(formData.get("name") ?? "").trim();
24	  if (name.length < 1 || name.length > 100) return { error: "Enter a valid name." };
25	  await db.user.update({ where: { id: user.id }, data: { name } });
26	  revalidatePath("/dashboard/settings");
27	  return { ok: true };
28	}
