30	export async function changePassword(prev: any, formData: FormData): Promise<{ error?: string; ok?: boolean }> {
31	  const user = await requireUser();
32	  const current = String(formData.get("current") ?? "");
33	  const next = String(formData.get("next") ?? "");
34	  if (next.length < 8) return { error: "New password must be at least 8 characters." };
35	  if (!(await bcrypt.compare(current, user.passwordHash))) return { error: "Current password is incorrect." };
36	  // Bump sessionVersion to evict every other outstanding session, then re-issue a
37	  // fresh token for THIS session so the user who changed the password stays in.
38	  await db.user.update({
39	    where: { id: user.id },
40	    data: { passwordHash: await bcrypt.hash(next, 12), sessionVersion: { increment: 1 } },
41	  });
42	  await createSession(user.id);
43	  return { ok: true };
44	}
