48	export async function addSshKey(prev: any, formData: FormData): Promise<{ error?: string }> {
49	  const user = await requireUser();
50	  const parsed = z
51	    .object({
52	      name: z.string().min(1).max(60),
53	      publicKey: z.string().min(20).max(4000).regex(/^(ssh-(rsa|ed25519)|ecdsa-sha2-\S+)\s+\S+/, "Not a valid OpenSSH public key"),
54	    })
55	    .safeParse({ name: formData.get("name"), publicKey: String(formData.get("publicKey") ?? "").trim() });
56	  if (!parsed.success) return { error: parsed.error.issues[0]?.message ?? "Invalid key." };
57	  await db.sshKey.create({ data: { userId: user.id, ...parsed.data } });
58	  revalidatePath("/dashboard/settings");
59	  return {};
60	}
