111	export async function requestPasswordReset(prev: any, formData: FormData): Promise<{ sent?: boolean }> {
112	  const email = String(formData.get("email") ?? "").trim().toLowerCase();
113	  // Throttle per email+IP (same helper login uses) to curb reset-email flooding
114	  // and enumeration probing. On limit, still report success below (no leak).
115	  const hdrs = await headers();
116	  const ip = (hdrs.get("x-forwarded-for") ?? "").split(",")[0]?.trim() || "unknown";
117	  const rl = checkRateLimit(`pwreset:${email}:${ip}`, { max: 5, windowMs: 15 * 60 * 1000 });
118	  if (!rl.ok) return { sent: true };
119	  // Always report success (don't leak which emails exist)
120	  const user = await db.user.findUnique({ where: { email } });
121	  if (user) {
122	    const { randomBytes, createHash } = await import("node:crypto");
123	    const token = randomBytes(32).toString("base64url");
124	    const tokenHash = createHash("sha256").update(token).digest("hex");
125	    await db.passwordResetToken.create({
126	      data: { userId: user.id, tokenHash, expiresAt: new Date(Date.now() + 3600_000) },
127	    });
128	    const { sendMail, emails } = await import("./mailer");
129	    const link = `${process.env.APP_URL ?? "https://nxeon.cloud"}/reset-password?token=${token}`;
130	    const tpl = emails.passwordReset(link);
131	    // Consult the notification policy, which classifies `password_reset` as
132	    // CRITICAL and therefore returns true without even loading the preferences.
133	    // The call is here so the POLICY decides, not this call site: a reset link is
134	    // the only route back into a locked-out account, so honouring an "Account
135	    // email: off" checkbox here would lock the customer out of their own account
136	    // permanently — the mirror image of swallowing a suspension warning.
137	    if (await mayDeliverTo(user.id, "password_reset", "email")) {
138	      await sendMail({ to: email, subject: tpl.subject, html: tpl.html });
139	    }
140	    await db.auditLog.create({ data: { userId: user.id, action: "user.password_reset_request" } });
141	  }
142	  return { sent: true };
143	}
