145	export async function resetPassword(prev: any, formData: FormData): Promise<{ error?: string; ok?: boolean }> {
146	  const token = String(formData.get("token") ?? "");
147	  const password = String(formData.get("password") ?? "");
148	  if (password.length < 8) return { error: "Password must be at least 8 characters." };
149	  const { createHash } = await import("node:crypto");
150	  const tokenHash = createHash("sha256").update(token).digest("hex");
151	  const row = await db.passwordResetToken.findUnique({ where: { tokenHash } });
152	  if (!row || row.usedAt || row.expiresAt < new Date()) {
153	    return { error: "This reset link is invalid or has expired. Request a new one." };
154	  }
155	  await db.$transaction([
156	    // Bump sessionVersion so any sessions predating the reset are evicted.
157	    db.user.update({
158	      where: { id: row.userId },
159	      data: { passwordHash: await bcrypt.hash(password, 12), sessionVersion: { increment: 1 } },
160	    }),
161	    db.passwordResetToken.update({ where: { id: row.id }, data: { usedAt: new Date() } }),
162	    db.auditLog.create({ data: { userId: row.userId, action: "user.password_reset_complete" } }),
163	  ]);
164	  return { ok: true };
165	}
