34	  return {
35	    host,
36	    port: Number(s.smtp_port || process.env.SMTP_PORT || 587),
37	    user: s.smtp_user || process.env.SMTP_USER || "",
38	    pass: s.smtp_pass || process.env.SMTP_PASS || "",
