49	function transport(c: Awaited<ReturnType<typeof loadSmtp>>) {
50	  if (!c.host) {
51	    // Local MTA fallback (Postfix/sendmail on the host)
52	    return nodemailer.createTransport({ sendmail: true, newline: "unix", path: "/usr/sbin/sendmail" });
53	  }
54	  // When the SMTP host is an internal IP (e.g. the mail VM at 10.20.0.10) but the
55	  // server presents a cert for its hostname (mail.nxeon.cloud), TLS validation
56	  // fails on an IP mismatch. `SMTP_TLS_SERVERNAME` lets us keep cert verification
57	  // on while telling TLS the name to validate against (and sets SNI accordingly).
58	  const servername = process.env.SMTP_TLS_SERVERNAME || undefined;
59	  return nodemailer.createTransport({
60	    host: c.host,
61	    port: c.port,
62	    secure: c.secure,
63	    auth: c.user ? { user: c.user, pass: c.pass } : undefined,
64	    ...(servername ? { tls: { servername } } : {}),
65	  });
66	}
