150	  // changes, data loss…) are declared non-suppressible in lib/prefs.ts and short
151	  // -circuit to true, so this costs nothing on the paths that matter most.
152	  if (opts.kind && opts.userId) {
153	    const allowed = await mayDeliverTo(opts.userId, opts.kind, "email");
154	    if (!allowed) {
155	      console.log(`[mail] suppressed ${opts.kind} to user ${opts.userId} by preference`);
156	      return false;
157	    }
158	  }
159	
160	  // Resolve subject/html: prefer explicit values, otherwise render the template.
161	  let subject = opts.subject ?? "";
162	  let html = opts.html ?? "";
163	  const templateKey = opts.template ?? null;
164	
165	  if (templateKey && !opts.html) {
