"use client";

import { useActionState } from "react";
import Link from "next/link";
import { requestPasswordReset, resetPassword } from "@/lib/actions-account";

export function ForgotForm() {
  const [state, action, pending] = useActionState(requestPasswordReset, {} as { sent?: boolean });
  if (state?.sent) {
    return (
      <div className="rounded-xl border border-emerald-500/30 bg-emerald-500/10 px-4 py-3 text-sm text-emerald-300">
        If an account exists for that email, a reset link is on its way. Check your inbox.
      </div>
    );
  }
  return (
    <form action={action} className="space-y-4">
      <div>
        <label className="label">Email</label>
        <input className="input" name="email" type="email" required autoComplete="email" />
      </div>
      <button className="btn-primary w-full" disabled={pending}>
        {pending ? "Sending…" : "Send reset link"}
      </button>
      <p className="text-center text-sm text-slate-400">
        <Link href="/login" className="text-brand-300 hover:underline">Back to sign in</Link>
      </p>
    </form>
  );
}

export function ResetForm({ token }: { token: string }) {
  const [state, action, pending] = useActionState(resetPassword, {} as { error?: string; ok?: boolean });
  if (state?.ok) {
    return (
      <div className="space-y-4 text-center">
        <div className="rounded-xl border border-emerald-500/30 bg-emerald-500/10 px-4 py-3 text-sm text-emerald-300">
          Your password has been reset.
        </div>
        <Link href="/login" className="btn-primary w-full">Sign in</Link>
      </div>
    );
  }
  return (
    <form action={action} className="space-y-4">
      <input type="hidden" name="token" value={token} />
      {state?.error && (
        <div className="rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-400">{state.error}</div>
      )}
      <div>
        <label className="label">New password</label>
        <input className="input" name="password" type="password" required minLength={8} autoComplete="new-password" />
      </div>
      <button className="btn-primary w-full" disabled={pending}>
        {pending ? "Saving…" : "Reset password"}
      </button>
    </form>
  );
}

