/**
 * The three rules `register()` in lib/actions.ts ACTUALLY enforces, restated
 * here so the checklist and the server agree.
 *
 * They used to disagree in both directions: the list demanded "Upper &
 * lowercase" and "A symbol" — neither of which the server checks — and never
 * mentioned the digit rule that it does. `PASSWORD!` therefore scored "Good"
 * and was rejected, while `abcdefg1` was accepted with two ticks missing. A
 * checklist that grades against rules nobody enforces is worse than no
 * checklist: it teaches the customer that the ticks are noise.
 *
 * If the regexes in `register()` change, change these with them.
 */
const REQUIRED_RULES = [
  { test: (v: string) => v.length >= 8, label: "8+ characters" },
  { test: (v: string) => /[a-zA-Z]/.test(v), label: "A letter" },
  { test: (v: string) => /[0-9]/.test(v), label: "A number" },
];

/** Genuinely optional — these make a password stronger but never reject it. */
const BONUS_RULES = [
  { test: (v: string) => /[a-z]/.test(v) && /[A-Z]/.test(v), label: "Upper & lowercase" },
  { test: (v: string) => /[^A-Za-z0-9]/.test(v), label: "A symbol" },
];

function PasswordField({
