  const bonus = BONUS_RULES.map((r) => ({ ok: r.test(val), label: r.label }));
  const score = [...required, ...bonus].filter((c) => c.ok).length;
  const strengthLabel = ["Too weak", "Too weak", "Weak", "Fair", "Good", "Strong"][score] ?? "Too weak";
  const barColor =
    ["bg-red-500", "bg-red-500", "bg-red-500", "bg-amber-500", "bg-yellow-400", "bg-emerald-500"][score] ??
    "bg-red-500";
  const total = required.length + bonus.length;

{requireStrong && val.length > 0 && (
  <div className="mt-2">
    <div className="flex items-center gap-2">
      <div className="h-1.5 flex-1 overflow-hidden rounded-full bg-white/10">
        <div
          className={`h-full ${barColor} transition-all duration-300`}
          style={{ width: `${(score / total) * 100}%` }}
        />
      </div>
      <span className="w-16 text-right text-[11px] text-slate-400">{strengthLabel}</span>
