model PasswordResetToken {
  id        String   @id @default(cuid())
  tokenHash String   @unique
  userId    String
  expiresAt DateTime
  usedAt    DateTime?
  createdAt DateTime @default(now())
}

/// A one-time link proving the holder can read `email`. Deliberately shaped like
/// PasswordResetToken (no relation field, SHA-256 hash only, never the raw
/// token) so a database leak hands out no working links.
///
/// `email` is stored on the token, unlike the reset table: a link is a claim
/// about ONE address, so if the account's address changes the outstanding link
/// must go stale rather than silently verify the new one.
/// Issued and redeemed exclusively through lib/email-verification.ts.
model EmailVerificationToken {
  id        String   @id @default(cuid())
