"use server";

import { revalidatePath } from "next/cache";
import { headers } from "next/headers";
import { requireUser } from "./auth";
import { sendVerificationEmail, isEmailVerified } from "./email-verification";

export type ResendState = { ok?: boolean; error?: string; message?: string };

/**
 * Re-send the verification link to the signed-in account's own address.
 *
 * Note what this action does NOT accept: an address. It only ever mails
 * `user.email`, read from the session on the server. An action that took an
 * address parameter would be an open relay pointed at our own domain — anyone
 * with an account could have Nxeon-branded mail delivered to a stranger.
 *
 * Throttled per user AND per source IP: the per-user key stops one account
 * hammering one mailbox, and the per-IP key stops one script cycling through
 * many fresh accounts to do the same thing at scale.
 */
export async function resendVerificationEmail(): Promise<ResendState> {
  const user = await requireUser();
  if (isEmailVerified(user)) {
    return { ok: true, message: "That address is already confirmed." };
  }
  const hdrs = await headers();
  const ip = (hdrs.get("x-forwarded-for") ?? "").split(",")[0]?.trim() || "unknown";
  const outcome = await sendVerificationEmail(user, { throttleKey: `${user.id}:${ip}` });
  switch (outcome) {
    case "sent":
      return { ok: true, message: `Sent. Check ${user.email} — the link is good for 24 hours.` };
    case "already_verified":
      return { ok: true, message: "That address is already confirmed." };
    case "rate_limited":
      return {
        error:
          "We've sent several links already. Check your spam folder, then try again in an hour — or open a support ticket and we'll sort it out with you.",
      };
    default:
      // Never pretend a send worked. The whole B4 defect class is a screen that
      // reports success while nothing happened.
      return { error: "We couldn't send that email just now. Please try again shortly, or contact support." };
  }
}

/** Form-action wrapper for `useActionState`. */
export async function resendVerificationAction(_prev: ResendState): Promise<ResendState> {
  const res = await resendVerificationEmail();
  revalidatePath("/dashboard");
  return res;
}

import { NextRequest, NextResponse } from "next/server";
import { consumeVerificationToken } from "@/lib/email-verification";

/**
 * The target of the link in the verification email.
 *
 * A route handler rather than a page because redeeming a token is a WRITE, and a
 * write during a server component's render is a bug waiting to happen — React
 * may render a component more than once, and Next may prefetch it. Handlers run
 * exactly once per request. The outcome is then shown by /verify-email, which
 * renders and mutates nothing.
 *
 * `GET` is correct here despite being a mutation: the customer arrives by
 * clicking a link in mail, and the "unsafe method" objection does not apply
 * because the token IS the intent and it is single-use. Mail security scanners
 * that pre-fetch links will consume the token — which is why
 * `consumeVerificationToken` reports an already-verified account as a success
 * rather than an error. A scanner that can read the link is inside the
 * recipient's own mail infrastructure, so it fetching the link is evidence of
 * exactly the control we are testing for, not a bypass of it.
 */
export async function GET(req: NextRequest) {
  const token = req.nextUrl.searchParams.get("token") ?? "";
  let status: string;
  try {
    status = await consumeVerificationToken(token);
  } catch (e) {
    console.error("[verify-email] failed to consume token:", e);
    status = "error";
  }
  const dest = new URL("/verify-email", req.nextUrl.origin);
  dest.searchParams.set("status", status);
  return NextResponse.redirect(dest, { status: 303 });
}

