import Link from "next/link";
import { currentUser } from "@/lib/auth";
import { ResendVerification } from "@/components/VerifyEmail";

export const dynamic = "force-dynamic";

/**
 * Where /api/auth/verify-email lands the customer. Renders the outcome and,
 * whenever the outcome is anything other than success, an actual way forward —
 * a resend button when we know who they are, a sign-in link when we don't.
 *
 * A verification page whose failure state is a full stop would recreate B4's
 * shape in a new place: a screen that tells you no and leaves you there.
 */
const OUTCOMES: Record<
  string,
  { tone: "ok" | "bad"; title: string; body: string; resend: boolean }
> = {
  ok: {
    tone: "ok",
    title: "Email confirmed",
    body: "Thanks — your address is verified. Everything on your account is now unlocked, including ordering.",
    resend: false,
  },
  already: {
    tone: "ok",
    title: "Already confirmed",
    body: "This address was verified previously, so there's nothing left to do.",
    resend: false,
  },
  expired: {
    tone: "bad",
    title: "That link has expired",
    body: "Verification links are good for 24 hours. Send yourself a fresh one and it'll work straight away.",
    resend: true,
  },
  stale: {
    tone: "bad",
    title: "That link is out of date",
    body: "It was sent to an address this account no longer uses. Request a new link for your current address.",
    resend: true,
  },
  invalid: {
    tone: "bad",
    title: "That link isn't valid",
    body: "It may have already been used, or been cut short by your email client. Sending a new one is the quickest fix.",
    resend: true,
  },
  error: {
    tone: "bad",
    title: "Something went wrong",
    body: "We couldn't check that link just now. Please try again in a moment.",
    resend: true,
  },
};

export default async function VerifyEmailPage({
  searchParams,
}: {
  searchParams: Promise<{ status?: string }>;
}) {
  const { status } = await searchParams;
  const outcome = OUTCOMES[status ?? ""] ?? OUTCOMES.invalid;
  const user = await currentUser();

  return (
    <main className="flex min-h-screen items-center justify-center p-6">
      <div className="w-full max-w-sm">
        <Link href="/" className="mb-8 flex items-center justify-center">
          {/* eslint-disable-next-line @next/next/no-img-element */}
          <img src="/logo.png" alt="Nxeon" style={{ height: 34, width: "auto" }} className="object-contain" />
        </Link>
        <div className="card glow-brand">
          <div
            className={
              outcome.tone === "ok"
                ? "rounded-xl border border-emerald-500/30 bg-emerald-500/10 px-4 py-3 text-sm text-emerald-300"
                : "rounded-xl border border-amber-500/30 bg-amber-500/10 px-4 py-3 text-sm text-amber-300"
            }
          >
            <p className="font-semibold">{outcome.title}</p>
            <p className="mt-1 opacity-90">{outcome.body}</p>
          </div>

          {outcome.resend && user && (
            <div className="mt-4">
              <ResendVerification email={user.email} />
            </div>
          )}
          {outcome.resend && !user && (
            <p className="mt-4 text-sm text-slate-400">
              <Link href="/login" className="text-brand-300 hover:underline">
                Sign in
              </Link>{" "}
              and we&apos;ll offer you a new link straight away.
            </p>
          )}

          <div className="mt-4 text-center text-sm">
            <Link href={user ? "/dashboard" : "/login"} className="text-brand-300 hover:underline">
              {user ? "Go to your dashboard" : "Sign in"}
            </Link>
          </div>
        </div>
      </div>
    </main>
  );
}

"use client";

import { useActionState } from "react";
import { resendVerificationAction, type ResendState } from "@/lib/actions-verify-email";

/**
 * The resend control. Deliberately reports the REAL outcome of the send —
 * "sent", "already confirmed", throttled, or failed — rather than an
 * unconditional "check your inbox". A button that always claims success is the
 * exact pattern that made the reset flow in H7 impossible to debug from the
 * customer's side, and it is what makes a broken mail transport invisible.
 */
function ResendButton({ label }: { label: string }) {
  const [state, action, pending] = useActionState<ResendState>(resendVerificationAction, {});
  return (
    <form action={action} className="space-y-2">
      <button className="btn-secondary w-full text-sm" disabled={pending}>
        {pending ? "Sending…" : label}
      </button>
      {state?.message && <p className="text-xs text-emerald-400">{state.message}</p>}
      {state?.error && <p className="text-xs text-amber-400">{state.error}</p>}
    </form>
  );
}

/** Standalone resend, used on the /verify-email outcome page. */
export function ResendVerification({ email }: { email: string }) {
  return (
    <div className="space-y-2">
      <p className="text-sm text-slate-400">
        We&apos;ll send a new link to <span className="text-slate-200">{email}</span>.
      </p>
      <ResendButton label="Send a new link" />
    </div>
  );
}

/**
 * Portal banner for an account that has not confirmed its address yet.
 *
 * Placed above the page content on every dashboard route rather than only on the
 * screen where the customer gets refused, because the refusal happens at
 * checkout — the worst possible moment to discover a prerequisite. It states
 * exactly what is restricted (buying, not the account), shows the address it is
 * waiting on so a typo is visible, and carries the resend inline. Informative,
 * not modal: nothing here blocks the page behind it.
 */
export function UnverifiedEmailBanner({ email }: { email: string }) {
  return (
    <div className="mb-6 rounded-xl border border-amber-500/30 bg-amber-500/10 p-4">
      <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
        <div className="min-w-0">
          <p className="text-sm font-semibold text-amber-300">Confirm your email address</p>
          <p className="mt-1 text-sm text-amber-200/80">
            We sent a link to <span className="font-medium text-amber-100 break-all">{email}</span>. Until you open
            it you can look around freely, but you won&apos;t be able to place an order — we won&apos;t charge for a
            server we can&apos;t send you the password for.
          </p>
        </div>
        <div className="w-full shrink-0 sm:w-56">
          <ResendButton label="Resend link" />
        </div>
      </div>
    </div>
  );
}

