import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { normalizeEmail, sameEmail } from "../lib/email-normalize.ts";
import {
  isEmailVerified,
  isGrandfathered,
  mayTransact,
  verificationRequiredMessage,
  VERIFICATION_ENFORCED_FROM,
  VERIFICATION_TTL_MS,
} from "../lib/email-verification.ts";

/**
 * The four authentication defects from the 2026-07-26 customer-journey
 * rehearsal (docs/QA-JOURNEY.md B4, H6, H7, M3).
 *
 * They share one shape, and it is not the shape of a typo: each one is a door
 * that reports itself open and is not. Correct credentials that never sign you
 * in. A reset link that is promised and never sent. A password that satisfies
 * the rule it is rejected for. An account that can spend money at an address
 * nobody has ever proved they can read. None of them throws, none of them logs,
 * and none of them is visible to the person they trap.
 *
 * Two of the four live in React rendering and one lives in a live Postgres
 * unique index, so neither can be exercised from a unit test. The policy that
 * decides them, though, is pure — and that half is tested for real below. The
 * source tripwires cover the rest: weaker than a browser, immeasurably stronger
 * than nothing, and they fail the moment the shape that caused the incident
 * reappears.
 */

/**
 * Source with comments removed.
 *
 * Every fix here carries a comment describing the bug it fixed — the H6 note
 * literally contains the words `name="email"` and "uncontrolled". A tripwire
 * that greps raw source would match its own incident note and pass on broken
 * code, or match the note and fail on correct code. Either way it teaches people
 * to ignore it. These assertions look at what the file DOES.
 */
function code(relative: string): string {
  return readFileSync(new URL(relative, import.meta.url), "utf8")
    .replace(/\/\*[\s\S]*?\*\//g, "")
    .replace(/^\s*\/\/.*$/gm, "");
}

const AUTH_FORMS = code("../components/AuthForms.tsx");
const ACTIONS = code("../lib/actions.ts");
const ACCOUNT = code("../lib/actions-account.ts");
const VERIFY = code("../lib/email-verification.ts");
const SCHEMA = code("../prisma/schema.prisma");
const PREFS = code("../lib/prefs.ts");

/* ================================================================== *
 * H6. Any customer who enables 2FA is permanently locked out
 *
 * The login email input was UNCONTROLLED while the password beside it was
 * controlled. React 19 resets uncontrolled fields after a form action settles,
 * and the 2FA path submits the SAME form twice: pass 1 returns `needs2fa`, pass
 * 2 must re-send email + password + code. React blanked the email between them,
 * `credsSchema` rejected the empty string, and the reply was a bare "Invalid
 * email or password." with no `needs2fa` — which unmounted the code field. With
 * correct credentials, there was no way through. Ever.
 * ================================================================== */

/** Every `<input>` in the file, as source text. All of them are self-closing. */
function inputTags(src: string): string[] {
  return [...src.matchAll(/<input\b[\s\S]*?\/>/g)].map((m) => m[0]);
}

test("H6: every input on the auth forms is controlled, so nothing survives on luck", () => {
  const tags = inputTags(AUTH_FORMS);
  assert.ok(tags.length >= 5, `expected the auth forms' inputs, found ${tags.length}`);
  for (const tag of tags) {
    const name = /name="([^"]+)"/.exec(tag)?.[1] ?? tag.slice(0, 60);
    // `value={` + `onChange={` is what makes React the owner of the field. An
    // input with neither is reset by the form action; an input with only
    // `value=` is frozen and unusable.
    assert.match(tag, /value=\{/, `<input name="${name}"> must be controlled — an uncontrolled field is blanked by the form action`);
    assert.match(tag, /onChange=\{/, `<input name="${name}"> has a value but no onChange, which freezes it`);
    assert.ok(
      !/defaultValue=/.test(tag),
      `<input name="${name}"> uses defaultValue, which the form action still resets`,
    );
  }
});

test("H6: the login form carries email, password and the 2FA code as React state", () => {
  const login = /export function LoginForm\(\)[\s\S]*?\n}/.exec(AUTH_FORMS)?.[0] ?? "";
  assert.ok(login, "found LoginForm");
  // The three fields that must survive between the two submits of one sign-in.
  assert.match(login, /const \[email, setEmail\] = useState\(/, "the email is React state");
  assert.match(login, /name="email"[\s\S]*?value=\{email\}/, "the email input reads that state");
  assert.match(login, /name="code"[\s\S]*?value=\{code\}/, "the 2FA code input is controlled too");
  // The password lives in PasswordField, which owns its own state.
  assert.match(login, /<PasswordField[\s\S]*?autoComplete="current-password"/, "the password field is the shared controlled one");
  // The whole bug was that the second submit posted an empty email. If the
  // 2FA branch is rendered, the email state must be what feeds the input.
  assert.ok(
    !/name="email"[^/]*\/>/.test(login.replace(/\s+/g, " ")) ||
      /name="email"[\s\S]*?value=\{email\}/.test(login),
    "the email input must never be a bare self-closing tag with no value",
  );
});

test("H6: a blank email is genuinely fatal, which is why the field cannot be allowed to blank", () => {
  // The other half of the incident: the server's shared credentials schema
  // rejects an empty email, and login answers that rejection WITHOUT `needs2fa`.
  // That combination is what unmounted the code field. Both halves are still
  // true — the fix is that the field can no longer arrive empty.
  assert.match(ACTIONS, /const credsSchema = z\.object\(\{/, "login and register share one credentials schema");
  assert.match(ACTIONS, /email: z\.string\(\)\.max\(200\)\.email\(/, "an empty email fails that schema");
  const login = /export async function login\([\s\S]*?\n}/.exec(ACTIONS)?.[0] ?? "";
  assert.ok(login, "found the login action");
  assert.match(
    login,
    /if \(!parsed\.success\) return \{ error: "Invalid email or password\." \};/,
    "a schema failure still answers without needs2fa — so the client must never send an empty email",
  );
  assert.match(login, /needs2fa: true/, "the 2FA challenge is still what re-renders the code field");
});

/* ================================================================== *
 * H7. A capitalised email at signup makes password reset silently impossible
 *
 * Register and login stored/queried the address verbatim against a
 * case-SENSITIVE Postgres unique index; forgot-password lowercased first. So
 * `Alice@Example.com` had a row no reset could find, and the correctly
 * non-enumerating "if an account exists…" reply hid it completely.
 * ================================================================== */

test("H7: normalizeEmail folds exactly the differences that are not real differences", () => {
  assert.equal(normalizeEmail("Alice@Example.com"), "alice@example.com");
  assert.equal(normalizeEmail("ALICE@EXAMPLE.COM"), "alice@example.com");
  assert.equal(normalizeEmail("  alice@example.com  "), "alice@example.com", "leading space from a paste or a keyboard");
  assert.equal(normalizeEmail("\talice@example.com\n"), "alice@example.com");
  // Idempotent — normalising an already-normalised address must be a no-op, or
  // a value could drift depending on how many times it was passed through.
  assert.equal(normalizeEmail(normalizeEmail("Alice@Example.com")), "alice@example.com");
  // Non-strings are the FormData reality (File | null). They must degrade to ""
  // and be rejected downstream, never crash and never become "null".
  assert.equal(normalizeEmail(null), "");
  assert.equal(normalizeEmail(undefined), "");
  assert.equal(normalizeEmail(123), "");
});

test("H7: normalizeEmail does NOT canonicalise things that are real differences", () => {
  // Gmail dots and +tags are provider conventions, not identity. Folding them
  // would merge addresses a customer considers separate — and could collide two
  // different people onto one account.
  assert.equal(normalizeEmail("a.l.i.c.e@gmail.com"), "a.l.i.c.e@gmail.com");
  assert.equal(normalizeEmail("alice+nxeon@gmail.com"), "alice+nxeon@gmail.com");
  assert.notEqual(normalizeEmail("alice@example.com"), normalizeEmail("alice@example.net"));
});

test("H7: the exact signup address from the incident now matches the reset lookup", () => {
  const signedUpAs = "Alice@Example.com"; // what a phone keyboard produces
  const typedIntoReset = "alice@example.com"; // what the customer types later
  assert.equal(normalizeEmail(signedUpAs), normalizeEmail(typedIntoReset));
  assert.ok(sameEmail(signedUpAs, typedIntoReset));
  assert.ok(sameEmail("  ALICE@example.com ", "alice@Example.COM"));
  // An empty address is never "the same" as anything, or a missing form field
  // would match a user row whose email somehow normalised to "".
  assert.ok(!sameEmail("", ""));
  assert.ok(!sameEmail(null, "alice@example.com"));
});

test("H7: every write and every lookup of an account address goes through the one helper", () => {
  // Register: the address is canonicalised BEFORE validation, so the row is
  // created in the same form the lookups use.
  const register = /export async function register\([\s\S]*?\n}/.exec(ACTIONS)?.[0] ?? "";
  assert.ok(register, "found the register action");
  assert.match(register, /email: normalizeEmail\(formData\.get\("email"\)\)/, "register normalises before it stores");

  // Login: same helper, so a mixed-case sign-in finds the row it created.
  const login = /export async function login\([\s\S]*?\n}/.exec(ACTIONS)?.[0] ?? "";
  assert.match(login, /email: normalizeEmail\(formData\.get\("email"\)\)/, "login normalises before it queries");

  // Reset: this one was ALREADY lowercasing. That is precisely why it diverged —
  // two independent implementations that happened to disagree. One definition now.
  assert.match(ACCOUNT, /normalizeEmail\(formData\.get\("email"\)\)/, "the reset lookup uses the shared helper");

  // The raw form value must never reach the schema or the query again.
  assert.ok(
    !/email:\s*formData\.get\("email"\)\s*[,}]/.test(ACTIONS),
    "no un-normalised email survives in lib/actions.ts",
  );
  // And no call site may re-implement the fold by hand — that is the drift that
  // produced the bug in the first place.
  assert.ok(
    !/formData\.get\("email"\)[^)]*\)\s*\.trim\(\)\.toLowerCase\(\)/.test(ACCOUNT),
    "the reset lookup no longer hand-rolls its own lowercasing",
  );
});

test("H7: the non-enumerating reset reply is preserved — the fix must not leak which accounts exist", () => {
  // Fixing the lookup must NOT be done by telling the customer "no such
  // account". The vague reply was the one correct thing about this flow.
  const reset = /export async function requestPasswordReset\([\s\S]*?\n}/.exec(ACCOUNT)?.[0] ?? "";
  assert.ok(reset, "found requestPasswordReset");
  assert.match(reset, /return \{ sent: true \}/, "the same answer is returned whether or not the user exists");
  assert.ok(!/error:/.test(reset), "no branch reports that an address is unknown");
});

/* ================================================================== *
 * B4. There is no email verification anywhere in the product
 * ================================================================== */

const NEW_ACCOUNT = new Date(VERIFICATION_ENFORCED_FROM.getTime() + 86_400_000);
const OLD_ACCOUNT = new Date(VERIFICATION_ENFORCED_FROM.getTime() - 86_400_000);

test("B4: an unverified new account cannot transact", () => {
  assert.equal(
    mayTransact({ emailVerifiedAt: null, createdAt: NEW_ACCOUNT }, true),
    false,
    "this is the whole point: no charge to an address nobody has proved they can read",
  );
});

test("B4: verifying unlocks it, and nothing else has to change", () => {
  assert.equal(mayTransact({ emailVerifiedAt: new Date(), createdAt: NEW_ACCOUNT }, true), true);
  assert.ok(isEmailVerified({ emailVerifiedAt: new Date() }));
  assert.ok(!isEmailVerified({ emailVerifiedAt: null }));
});

test("B4: accounts that predate the feature are grandfathered, not retroactively locked out", () => {
  // The regression this prevents is severe and silent: every existing paying
  // customer has emailVerifiedAt NULL because they were never asked. Enforcing
  // against them would refuse them a renewal of a server they already own.
  assert.ok(isGrandfathered({ createdAt: OLD_ACCOUNT }));
  assert.ok(!isGrandfathered({ createdAt: NEW_ACCOUNT }));
  assert.equal(mayTransact({ emailVerifiedAt: null, createdAt: OLD_ACCOUNT }, true), true);
  // Exactly at the boundary the account is NOT grandfathered — the cutoff is the
  // moment enforcement begins, so ">= cutoff" must be gated.
  assert.ok(!isGrandfathered({ createdAt: new Date(VERIFICATION_ENFORCED_FROM.getTime()) }));
});

test("B4: the gate stands down when the instance cannot send the email that opens it", () => {
  // A gate whose key can never be delivered is not a gate, it is an outage —
  // and it would close the entire purchase funnel on an SMTP misconfiguration,
  // silently. lib/prefs.ts makes the same fail-open call for the same reason.
  assert.equal(mayTransact({ emailVerifiedAt: null, createdAt: NEW_ACCOUNT }, false), true);
  // …but a working mail transport re-arms it immediately.
  assert.equal(mayTransact({ emailVerifiedAt: null, createdAt: NEW_ACCOUNT }, true), false);
});

test("B4: the refusal names the address and points at the way out", () => {
  const msg = verificationRequiredMessage("alice@example.com");
  assert.match(msg, /alice@example\.com/, "showing the address is how a typo becomes visible");
  assert.match(msg, /Settings/i, "a refusal without a remedy is the dead end we are removing");
  assert.ok(msg.length < 400, "it has to fit in an error box");
});

test("B4: the schema carries the field and the token, additively", () => {
  assert.match(SCHEMA, /emailVerifiedAt DateTime\?/, "nullable — never a default, never backfilled with a fiction");
  assert.match(SCHEMA, /model EmailVerificationToken \{/, "the token model exists");
  assert.match(SCHEMA, /model EmailVerificationToken \{[\s\S]*?tokenHash String   @unique/, "tokens are looked up by hash");
  assert.match(SCHEMA, /model EmailVerificationToken \{[\s\S]*?expiresAt DateTime/, "a token that never expires is a permanent key");
  assert.match(SCHEMA, /model EmailVerificationToken \{[\s\S]*?usedAt    DateTime\?/, "single use");
  assert.match(SCHEMA, /model EmailVerificationToken \{[\s\S]*?email     String/, "the token names the ONE address it can verify");
});

test("B4: the raw token is never persisted", () => {
  assert.match(VERIFY, /createHash\("sha256"\)/, "only the digest is stored, as PasswordResetToken does");
  assert.match(VERIFY, /randomBytes\(32\)/, "and the token itself is unguessable");
  assert.ok(!/tokenHash: raw\b/.test(VERIFY), "the raw token is never written to the tokenHash column");
  assert.ok(VERIFY.includes("hashToken(raw)"), "the value that reaches the database is hashed");
  assert.ok(VERIFICATION_TTL_MS > 0 && VERIFICATION_TTL_MS <= 7 * 86_400_000, "the link expires within a week");
});

test("B4: verification is classified so a preference cannot make it undeliverable", () => {
  // Same reasoning as password_reset: this message is the only route past the
  // purchase gate, so an unticked checkbox must not be able to strand someone
  // behind a door we never handed them the key to.
  assert.match(PREFS, /email_verify: "CRITICAL"/, "the verification link is non-suppressible");
  assert.match(VERIFY, /kind: "email_verify"/, "and the send actually declares its kind, so the policy decides");
  assert.match(VERIFY, /userId: user\.id/, "the policy needs the user to decide at all");
});

test("B4: signing up and browsing are NOT gated — only buying is", () => {
  const register = /export async function register\([\s\S]*?\n}/.exec(ACTIONS)?.[0] ?? "";
  // The send must not be able to fail the signup.
  assert.match(register, /try \{[\s\S]*?sendVerificationEmail\(user\)[\s\S]*?\} catch/, "the send is best-effort");
  assert.match(register, /redirect\("\/dashboard"\)/, "the customer still lands in the portal");
  // Nothing in register refuses on verification — that would be the gate on the
  // front door we explicitly rejected.
  assert.ok(!/emailVerificationError/.test(register), "register never gates itself");
});

test("B4: every customer-initiated purchase path consults the gate", () => {
  const sites: [string, string][] = [
    ["../lib/actions.ts", "orderServer"],
    ["../lib/actions.ts", "payAndDeploy"],
    ["../lib/actions.ts", "renewNow"],
    ["../lib/actions-domains.ts", "purchaseDomain"],
    ["../lib/actions-domains.ts", "renewDomainAction"],
    ["../lib/actions-domains-transfer.ts", "submitTransferIn"],
    ["../lib/actions-email-hosting.ts", "orderEmailHosting"],
    ["../lib/actions-gameplans.ts", "orderGameServer"],
    ["../lib/actions-volumes.ts", "orderVolume"],
    ["../lib/actions-server.ts", "resizeServer"],
    ["../lib/actions-disk.ts", "expandServerDisk"],
    ["../lib/actions-affiliate.ts", "requestAffiliatePayout"],
  ];
  for (const [file, fn] of sites) {
    const src = code(file);
    const body = new RegExp(`export async function ${fn}\\(([\\s\\S]*?)\\n}`).exec(src)?.[0] ?? "";
    assert.ok(body, `found ${fn} in ${file}`);
    assert.match(
      body,
      /await emailVerificationError\(user\)/,
      `${file}:${fn} must consult the verification gate before it takes money`,
    );
    assert.match(body, /return \{ error: unverified/, `${file}:${fn} must surface the refusal, not throw a blank page`);
  }
});

test("B4: paths that give value BACK are deliberately not gated", () => {
  // Gating a refund, a downgrade or a restore would invent a new dead end while
  // protecting nobody — there is no charge to an unreachable person in any of
  // them. This asserts the line stays where it was argued, not merely that some
  // gate exists somewhere.
  const lifecycle = code("../lib/actions-server-lifecycle.ts");
  const down = /export async function resizeServerDown\([\s\S]*?\n}/.exec(lifecycle)?.[0] ?? "";
  assert.ok(down, "found resizeServerDown");
  assert.ok(!/emailVerificationError/.test(down), "a downgrade refunds the customer and must stay open");
  const ops = code("../lib/actions-server-ops.ts");
  assert.ok(!/emailVerificationError/.test(ops), "backups and restores of an already-paid service stay open");
});

test("B4: the resend action cannot be pointed at somebody else's mailbox", () => {
  // An action that accepted an address would be an open relay wearing our
  // branding: any account holder could have Nxeon mail delivered to a stranger.
  const resend = code("../lib/actions-verify-email.ts");
  assert.match(resend, /export async function resendVerificationEmail\(\): Promise/, "it takes no address");
  assert.match(resend, /const user = await requireUser\(\)/, "the address comes from the session");
  assert.match(resend, /throttleKey: `\$\{user\.id\}:\$\{ip\}`/, "throttled per account AND per source");
  assert.match(VERIFY, /RESEND_LIMIT/, "the throttle is a real limit, not a comment");
  // It must report the truth. "Sent" when nothing was sent is the B4 defect
  // class reappearing inside B4's own fix.
  assert.match(resend, /case "rate_limited":/, "a throttled resend says so");
  assert.match(resend, /couldn't send/, "a failed send says so");
});

/* ================================================================== *
 * M3. The register error states a rule the password already satisfies,
 *     and wipes the form
 * ================================================================== */

test("M3: register reports the issue it actually found", () => {
  const register = /export async function register\([\s\S]*?\n}/.exec(ACTIONS)?.[0] ?? "";
  assert.match(
    register,
    /return \{ error: parsed\.error\.issues\[0\]\?\.message/,
    "the precise per-rule message is surfaced, not collapsed",
  );
  // The exact string a customer with a valid 8-character password was shown.
  assert.ok(
    !/Enter a valid email, name, and password \(min 8 chars\)/.test(ACTIONS),
    "the flat catch-all message that named the wrong rule is gone",
  );
  // Every branch of the schema must carry a message, or the collapse comes back
  // as an unreadable zod default.
  assert.match(register, /min\(8, "Password must be at least 8 characters"\)/);
  assert.match(register, /regex\(\/\[a-zA-Z\]\/, "Password must include a letter"\)/);
  assert.match(register, /regex\(\/\[0-9\]\/, "Password must include a number"\)/);
  assert.match(register, /min\(1, "Enter your name"\)/);
  assert.match(ACTIONS, /email\(\"Enter a valid email address\"\)/);
});

test("M3: the strength checklist grades against the rules the server enforces", () => {
  const required = /const REQUIRED_RULES = \[[\s\S]*?\];/.exec(AUTH_FORMS)?.[0] ?? "";
  const bonus = /const BONUS_RULES = \[[\s\S]*?\];/.exec(AUTH_FORMS)?.[0] ?? "";
  assert.ok(required && bonus, "the checklist separates what is enforced from what is advice");

  // The three the server actually applies, and only those.
  assert.match(required, /v\.length >= 8/, "length is enforced and listed");
  assert.match(required, /\/\[a-zA-Z\]\/\.test\(v\)/, "the letter rule is enforced and was never listed before");
  assert.match(required, /\/\[0-9\]\/\.test\(v\)/, "the digit rule is enforced and was never listed before");

  // The two the server does NOT apply must not sit in the required list —
  // `PASSWORD!` scored "Good" against them and was still rejected.
  assert.ok(!/A symbol/.test(required), "a symbol is not required by the server, so it cannot be listed as required");
  assert.ok(!/Upper & lowercase/.test(required), "mixed case is not required by the server either");
  assert.match(bonus, /A symbol/, "it is still offered as advice");
  assert.match(bonus, /Upper & lowercase/);

  // Anything the server enforces must be visible somewhere in the list.
  for (const rule of ["8+ characters", "A letter", "A number"]) {
    assert.ok(required.includes(rule), `"${rule}" is enforced and must be shown`);
  }
});

test("M3: a rejected signup keeps everything the customer typed", () => {
  const register = /export function RegisterForm\(\)[\s\S]*?\n}/.exec(AUTH_FORMS)?.[0] ?? "";
  assert.ok(register, "found RegisterForm");
  assert.match(register, /const \[name, setName\] = useState\(/, "the name is React state");
  assert.match(register, /const \[email, setEmail\] = useState\(/, "the email is React state");
  assert.match(register, /name="name"[\s\S]*?value=\{name\}/, "and the inputs read it");
  assert.match(register, /name="email"[\s\S]*?value=\{email\}/);
  // The password is controlled inside PasswordField, so it survives too —
  // which matters most here, since the password is the field being corrected.
  assert.match(AUTH_FORMS, /name="password"[\s\S]*?value=\{val\}/, "the password survives a rejection as well");
});

